  route.delete('/api/buddies/:buddyId', 400, async (req, res) => {
    const store = await getStore();
    const buddy = store.getBuddy(req.params.buddyId);
    if (!buddy) {
      res.status(404).json({ error: 'Buddy not found' });
      return;
    }
    const automations = store.listAutomations({ buddy: buddy.id });
    const automationIds = new Set(automations.map((automation) => automation.id));
    const runs = store
      .listNonterminalAutomationRuns()
      .filter((run) => automationIds.has(run.automation_id));
    const scheduler = getScheduler();
    if (runs.length && !scheduler) {
      res.status(503).json({ error: 'Buddy scheduler is not ready to cancel active work' });
      return;
    }
    // Revoke new dispatches before awaiting cancellation. Repeating DELETE safely
    // finishes cleanup after an interrupted request; the durable archive is retained.
    store.updateBuddy(buddy.id, { status: 'archived' });
    for (const automation of automations) {
      store.updateAutomation(automation.id, { enabled: false, nextRunAt: null });
    }
    await dependencies.onBuddyArchived?.(buddy.id);
    for (const run of runs) await scheduler!.cancel(run.id);
    store.recordAuditEvent({
      buddy: buddy.id,
      workspace: (store.listBuddyWorkspaces(buddy.id)[0] as { id: string }).id,
      operation: 'buddy.archive',
      payload: { source: 'owner:settings' },
    });
    res.json({ archived: true });
  });

  route.get('/api/buddies/:buddyId', 500, async (req, res) => {
    const buddies = await getStore();
    const buddy = buddies.getBuddy(req.params.buddyId);
    if (!buddy) {
      res.status(404).json({ error: 'Buddy not found' });
      return;
    }
    const automations = buddies.listAutomations({ buddy: buddy.id });
    const reviews = buddies.listReviews({ buddy: buddy.id });
    const reviewConversationIds = new Set(
      reviews
        .map((review) => review.conversation_id)
        .filter((conversationId): conversationId is string => Boolean(conversationId))
    );
    const linked = await Promise.all(
      buddies.listConversationLinks(buddy.id).map(async (value) => {
        const conversation = value as Record<string, unknown>;
        const conversationId =
          typeof conversation.unleashd_conversation_id === 'string'
            ? conversation.unleashd_conversation_id
            : typeof conversation.conversation_id === 'string'
              ? conversation.conversation_id
              : null;
        // Deleting a conversation only terminalizes its link row, so without
        // this the page keeps listing threads that can never be opened again.
        // Links with no conversation id (provider-session only) are kept —
        // there is nothing to tombstone them against.
        if (conversationId && (await isConversationDeleted(conversationId))) {
          return null;
        }
        return {
          ...conversation,
          kind:
            conversationId && buddies.getAutomationRunByConversationId(conversationId)
              ? 'automation'
              : conversationId && reviewConversationIds.has(conversationId)
                ? 'review'
                : 'conversation',
        };
      })
    );
    const conversations = linked.filter((conversation) => conversation !== null);
    res.json({
      buddy,
      ...buddies.getBuddyTeamState(buddy.id),
      messages: buddies.listMessages({ buddy: buddy.id }).map((message) => ({
        ...message,
        execution: messageExecution(buddies, message.id),
      })),
      workspaces: buddies.listBuddyWorkspaces(buddy.id),
      projects: buddies.listBuddyOwnedProjects({ buddy: buddy.id, includeClosed: true }),
      legacyWorkItems: buddies.listWorkItems({ buddy: buddy.id, includeClosed: true }),
      conversations,
      automations,
      relationships: buddies.listBuddyRelationships(buddy.id),
      skills: buddies.listBuddySkills(buddy.id),
      delegations: buddies.listDelegations({ buddy: buddy.id }),
      reviews,
      approvals: buddies.listApprovalRequests({ buddy: buddy.id }),
    });
  });

  route.patch('/api/buddies/:buddyId/profile', 400, async (req, res) => {
    if (req.body?.hireQuota !== undefined) {
      res
        .status(400)
        .json({ error: 'Hiring quotas are no longer used; configure relationships instead' });
      return;
    }

    const providerResult = ProviderSchema.safeParse(req.body?.provider);
    if (!providerResult.success) {
      res.status(400).json({ error: 'A valid provider is required' });
      return;
    }
    const provider = providerResult.data;
    try {
      assertBuddyProviderSupportsMcp(provider);
    } catch (error) {
      res.status(400).json({
        error: error instanceof Error ? error.message : String(error),
      });
      return;
    }
    const model =
      typeof req.body?.model === 'string' && req.body.model.trim()
        ? normalizeModelId(provider, req.body.model.trim())
        : null;
    const reasoningEffort =
      typeof req.body?.reasoningEffort === 'string' && req.body.reasoningEffort.trim()
        ? req.body.reasoningEffort.trim()
        : null;

    if (!isModelIdValidForProvider(provider, model ?? undefined)) {
      res.status(400).json({
        error: `Invalid ${provider} model; expected ${modelValidationHint(provider)}`,
      });
      return;
    }
    if (!isEffortValidForProvider(provider, reasoningEffort)) {
      res.status(400).json({
        error: `Invalid ${provider} reasoning effort`,
      });
      return;
    }

    const buddies = await getStore();
    res.json(
      buddies.updateBuddy(req.params.buddyId, {
        provider,
        model,
        reasoningEffort,
      })
    );
  });

  route.get('/api/buddies/:buddyId/soul', 404, async (req, res) => {
    res.json(readBuddySoul(await getStore(), req.params.buddyId));
  });

  // The caller supplies the revision it actually read. Never replace it with
  // the server's latest revision, which silently overwrites concurrent edits.
  route.put('/api/buddies/:buddyId/soul', 'memory', async (req, res) => {
    if (
      typeof req.body?.content === 'string' &&
      req.body.content.trim().length > BUDDY_SOUL_MAX_CHARACTERS
    ) {
      res.status(413).json({ error: `Soul exceeds ${BUDDY_SOUL_MAX_CHARACTERS} characters` });
      return;
    }
    const buddies = await getStore();
    if (!buddies.getBuddy(req.params.buddyId)) {
      res.status(404).json({ error: 'Buddy not found' });
      return;
    }
    res.json(
      updateBuddySoul(buddies, req.params.buddyId, req.body, 'owner:http', {
        source: 'http-soul-route',
      })
    );
  });

  route.get('/api/buddies/:buddyId/context', 404, async (req, res) => {
    const buddies = await getStore();
    res.json(
      buddies.getBuddyContext(req.params.buddyId, {
        workspace: typeof req.query.workspaceId === 'string' ? req.query.workspaceId : undefined,
        project: typeof req.query.projectId === 'string' ? req.query.projectId : undefined,
      })
    );
  });

  route.post('/api/buddies/:buddyId/relationships', 400, async (req, res) => {
    const buddies = await getStore();
    res.status(201).json(
      buddies.setBuddyRelationship({
        fromBuddy: req.params.buddyId,
        toBuddy: req.body?.toBuddyId,
        kind: req.body?.kind,
      })
    );
  });

  route.post('/api/buddies/:buddyId/skills', 400, async (req, res) => {
    const buddies = await getStore();
    res.status(201).json(
      buddies.assignBuddySkill({
        buddy: req.params.buddyId,
        name: req.body?.name,
        instructionPath: req.body?.instructionPath,
        mode: req.body?.mode,
      })
    );
  });

  // Compatibility adapters for already-loaded clients. All new work uses messages.
  route.post('/api/buddies/:buddyId/delegations', 400, async (req, res) => {
    const input = req.body ?? {};
    res.status(201).json(
      await sendMessageFromRequest(req, {
        to: input.toBuddyId,
        purpose: 'delegation',
        body: input.purpose,
        projectId: input.buddyProjectId,
        evidence: [],
      })
    );
  });

  route.patch('/api/buddies/delegations/:delegationId', 400, async (req, res) => {
    const buddies = await getStore();
    res.json(buddies.updateDelegation(req.params.delegationId, req.body ?? {}));
  });

  route.post('/api/buddies/:buddyId/review-requests', 400, async (req, res) => {
    const input = req.body ?? {};
    const evidence = Array.isArray(input.evidence)
      ? input.evidence.map((item: unknown) =>
          typeof item === 'string' ? item : JSON.stringify(item)
        )
      : [];
    res.status(201).json(
      await sendMessageFromRequest(req, {
        to: input.reviewerBuddyId,
        purpose: 'review',
        body: `Review Buddy ${String(input.subjectBuddyId)}. ${String(input.purpose ?? 'Review employee work')}`,
        evidence: [
          ...evidence,
          ...(typeof input.buddyProjectId === 'string' ? [`project:${input.buddyProjectId}`] : []),
        ],
      })
    );
  });

  // Direct review creation previously impersonated its recipient as the sender.
  // Clients now choose a sender and use /messages or /review-requests.
  route.post('/api/buddies/:buddyId/reviews', 410, async (_req, res) => {
    res.status(410).json({ error: 'Choose a sender and use /api/buddies/:buddyId/messages' });
  });

  route.patch('/api/buddies/reviews/:reviewId', 400, async (req, res) => {
    const buddies = await getStore();
    res.json(buddies.updateReview(req.params.reviewId, req.body ?? {}));
  });

  route.get('/api/buddies/:buddyId/memory/scopes', 'memory', async (req, res) => {
    const store = await getStore();
    const context = memoryHttpContext(store, req.params.buddyId, req);
    const scopes = knowledgeStore(store).listKnowledgeScopes(context.buddyId, {
      actor: 'owner',
      workspaceId: context.workspaceId,
    });
    const projects = store.listBuddyOwnedProjects({
      buddy: context.buddyId,
      workspace: context.workspaceId,
      includeClosed: true,
    }) as Array<{ id: string; title: string }>;
    for (const project of projects)
      if (!scopes.some((s) => s.kind === 'project' && s.projectId === project.id))
        scopes.push({ kind: 'project', projectId: project.id });
    res.json([
      { label: 'Owner memory', scope: null },
      ...scopes.map((scope) => ({
        scope,
        label:
          scope.kind === 'workspace'
            ? 'Workspace work'
            : scope.kind === 'project'
              ? `Project: ${projects.find((p) => p.id === scope.projectId)?.title ?? scope.projectId}`
              : `Owner conversation: ${scope.conversationId}`,
      })),
    ]);
  });

  route.get('/api/buddies/:buddyId/memory', 404, async (req, res) => {
    const buddies = await getStore();
    const scope = memoryAudience(req);
    if (!scope) return void res.json(buddies.readBuddyMemory(req.params.buddyId));
    const { buddyId, workspaceId } = memoryHttpContext(buddies, req.params.buddyId, req);
    const ledger = knowledgeStore(buddies);
    const authority = { actor: 'owner', workspaceId };
    const read = (kind: 'working' | 'long_term') =>
      ledger.readKnowledgeDocument({ targetBuddyId: buddyId, scope, kind }, authority);
    const working = read('working');
    const longTerm = read('long_term');
    res.json({
      working: working.content,
      longTerm: longTerm.content,
      workingRevision: working.revision,
      longTermRevision: longTerm.revision,
      generation: Math.max(working.revision, longTerm.revision),
      operations: { updateMemory: true, rememberNote: true, recall: true },
      notes: ledger
        .listKnowledgeDocuments(
          { targetBuddyId: buddyId, scope, kinds: ['note'], limit: 20 },
          authority
        )
        .filter((note) => note.ref.targetBuddyId === buddyId)
        .map((note) => ({
          id: note.id,
          topic: note.ref.name,
          kind: 'note',
          content: note.content,
        })),
    });
  });

  route.put('/api/buddies/:buddyId/memory/:document', 'memory', async (req, res) => {
    const buddies = await getStore();
    const context = memoryHttpContext(buddies, req.params.buddyId, req);
    const document = req.params.document;
    const scope = memoryAudience(req);
    if (scope) {
      const parsed = BuddyOperationInputSchemas['buddy.update_memory'].parse({
        ...memoryPayload(req),
        doc: document,
      });
      res.json(
        scopedDocumentOperation(
          buddies,
          { targetBuddyId: context.buddyId, kind: parsed.doc, scope },
          { ...parsed, key: parsed.key ?? createId() },
          { actor: 'owner', workspaceId: context.workspaceId }
        )
      );
      return;
    }
    const result = new BuddyOperationsService(buddies, context).execute('buddy.update_memory', {
      ...memoryPayload(req),
      doc: document,
    });
    res.json(result);
  });

  route.post('/api/buddies/:buddyId/memory/notes', 'memory', async (req, res) => {
    const buddies = await getStore();
    const context = memoryHttpContext(buddies, req.params.buddyId, req);
    const scope = memoryAudience(req);
    if (scope) {
      const input = BuddyOperationInputSchemas['buddy.remember_note'].parse(memoryPayload(req));
      res.status(201).json({
        data: scopedNote(
          buddies,
          { actor: 'owner', workspaceId: context.workspaceId, scope },
          input,
          context.buddyId
        ),
      });
      return;
    }
    const result = new BuddyOperationsService(buddies, context).execute('buddy.remember_note', {
      ...memoryPayload(req),
      body:
        typeof req.body?.body === 'string'
          ? req.body.body
          : typeof req.body?.content === 'string'
            ? req.body.content
            : undefined,
    });
    res.status(201).json(result);
  });

  route.post('/api/buddies/:buddyId/memory/recall', 'memory', async (req, res) => {
    const buddies = await getStore();
    const context = memoryHttpContext(buddies, req.params.buddyId, req);
    const scope = memoryAudience(req);
    if (scope) {
      const input = BuddyOperationInputSchemas['buddy.recall'].parse(memoryPayload(req));
      res.json({
        data: recallKnowledge(
          buddies,
          { actor: 'owner', workspaceId: context.workspaceId, scope },
          input,
          context.buddyId
        ),
      });
      return;
    }
    const result = new BuddyOperationsService(buddies, context).execute('buddy.recall', {
      ...memoryPayload(req),
    });
    res.json(result);
  });

  route.get('/api/buddies/:buddyId/projects', 400, async (req, res) => {
    const buddies = await getStore();
    res.json(
      buddies.listBuddyOwnedProjects({
        buddy: req.params.buddyId,
        workspace: typeof req.query.workspaceId === 'string' ? req.query.workspaceId : undefined,
        includeClosed: req.query.includeClosed === 'true',
      })
    );
  });

  route.post('/api/buddies/:buddyId/projects', 400, async (req, res) => {
    const { workspaceId, title, definitionOfDone, ...optional } = req.body ?? {};
    if (
      typeof workspaceId !== 'string' ||
      typeof title !== 'string' ||
      typeof definitionOfDone !== 'string'
    ) {
      res.status(400).json({ error: 'workspaceId, title, and definitionOfDone are required' });
      return;
    }
    const buddies = await getStore();
    res.status(201).json(
      coordinationStore(buddies).createCoordinatedProject(
        {
          ...BuddyOperationInputSchemas['buddy.new_project'].parse({
            ...optional,
            title,
            definitionOfDone,
          }),
          workspaceId,
          ownerId: optional.ownerId ?? req.params.buddyId,
        },
        { actor: 'owner', key: req.get('Idempotency-Key') ?? optional.key ?? createId() }
      )
    );
  });

  route.get('/api/buddies/projects/:projectId/comments', 400, async (req, res) => {
    const store = coordinationStore(await getStore());
    const project = store.getBuddyProject(req.params.projectId) as { workspace_id: string } | null;
    if (!project) {
      res.status(404).json({ error: 'Project not found' });
      return;
    }
    const query = BuddyTaskCommentsQuerySchema.parse({
      limit: req.query.limit === undefined ? undefined : Number(req.query.limit),
      cursor: req.query.cursor,
    });
    res.json(
      BuddyTaskCommentsPageSchema.parse(
        store.listTaskComments(
          { ...query, projectId: req.params.projectId },
          { actor: 'owner', workspaceId: project.workspace_id }
        )
      )
    );
  });

  route.post('/api/buddies/projects/:projectId/comments', 400, async (req, res) => {
    const store = coordinationStore(await getStore());
    const project = store.getBuddyProject(req.params.projectId) as { workspace_id: string } | null;
    if (!project) {
      res.status(404).json({ error: 'Project not found' });
      return;
    }
    const input = BuddyTaskCommentInputSchema.parse(req.body);
    res
      .status(201)
      .json(
        BuddyTaskCommentSchema.parse(
          store.appendTaskComment(
            { ...input, projectId: req.params.projectId },
            { actor: 'owner', workspaceId: project.workspace_id }
          )
        )
      );
  });

  route.patch('/api/buddies/projects/:projectId', 400, async (req, res) => {
    const buddies = await getStore();
    const project = buddies.getBuddyProject(req.params.projectId) as { revision: number } | null;
    if (!project) throw new Error('Project not found');
    const changes = BuddyOperationInputSchemas['buddy.update_project'].parse(req.body ?? {});
    res.json(
      coordinationStore(buddies).updateCoordinatedProject(
        req.params.projectId,
        { ...changes, baseRevision: changes.baseRevision ?? project.revision },
        { actor: 'owner', key: req.get('Idempotency-Key') ?? changes.key ?? createId() }
      )
    );
  });

  route.get('/api/buddies/:buddyId/automations', 400, async (req, res) => {
    const buddies = await getStore();
    res.json(buddies.listAutomations({ buddy: req.params.buddyId }));
  });

  app.post('/api/buddies/resources/:operation', async (request, response) => {
    try {
      const store = await dependencies.getStore();
      const result = executeOwnerResource(
        store,
        request.params.operation as OwnerResourceName,
        request.body,
        {
          ownerInputId: `http:${dependencies.createId()}`,
          conversationId: null,
          workspaceIds: ownerWorkspaceIds(store),
        }
      );
      response.json(result);
    } catch (error) {
      dependencies.sendError(response, error, 400);
    }
  });
  app.get('/api/buddies/automations/health', (_req: Request, res: Response) => {
    const scheduler = getScheduler();
    if (!scheduler) {
      res.status(503).json({ error: 'Buddy scheduler is not ready' });
      return;
    }
    res.json(scheduler.health());
  });

  route.post('/api/buddies/:buddyId/automations', 400, async (req, res) => {
    const buddies = await getStore();
    const scheduleCandidate = {
      schedule_kind: req.body?.scheduleKind,
      schedule_expression: req.body?.scheduleExpression,
      timezone: req.body?.timezone ?? 'UTC',
    } as BuddyAutomation;
    // Validate and compute before persistence. A 400 must never leave an
    // enabled definition whose schedule cannot be evaluated.
    const nextRunAt = getNextAutomationRunAt(scheduleCandidate, new Date());
    const automation = buddies.createAutomation({
      ...req.body,
      buddy: req.params.buddyId,
      workspace: req.body?.workspaceId,
      project: req.body?.projectId,
      nextRunAt,
    });
    res.status(201).json(automation);
  });

  route.patch('/api/buddies/automations/:automationId', 400, async (req, res) => {
    const buddies = await getStore();
    const current = buddies.getAutomation(req.params.automationId);
    if (!current) throw new Error(`automation not found: ${req.params.automationId}`);
    if (buddies.getBuddy(current.buddy_id)?.status === 'archived') {
      res.status(404).json({ error: 'Buddy not found' });
      return;
    }
    let changes = req.body ?? {};
    if (
      req.body?.nextRunAt === undefined &&
      ((req.body?.enabled === true && current.next_run_at === null) ||
        req.body?.scheduleKind !== undefined ||
        req.body?.scheduleExpression !== undefined ||
        req.body?.timezone !== undefined)
    ) {
      const candidate = {
        ...current,
        schedule_kind: req.body.scheduleKind ?? current.schedule_kind,
        schedule_expression: req.body.scheduleExpression ?? current.schedule_expression,
        timezone: req.body.timezone ?? current.timezone,
      };
      changes = { ...changes, nextRunAt: getNextAutomationRunAt(candidate, new Date()) };
    }
    const automation = buddies.updateAutomation(current.id, changes);
    res.json(automation);
  });

  route.delete('/api/buddies/automations/:automationId', 400, async (req, res) => {
    const buddies = await getStore();
    const activeRuns = buddies
      .listNonterminalAutomationRuns()
      .filter((run) => run.automation_id === req.params.automationId);
    if (activeRuns.length) {
      const scheduler = getScheduler();
      if (!scheduler) {
        res.status(503).json({ error: 'Buddy scheduler is not ready to cancel active work' });
        return;
      }
      for (const run of activeRuns) await scheduler.cancel(run.id);
    }
    res.json(buddies.archiveAutomation(req.params.automationId));
  });

  route.post('/api/buddies/automations/:automationId/run', 400, async (req, res) => {
    const scheduler = getScheduler();
    if (!scheduler) {
      res.status(503).json({ error: 'Buddy scheduler is not ready' });
      return;
    }
    const run = await scheduler.runNow(
      req.params.automationId,
      typeof req.body?.key === 'string' ? req.body.key : undefined
    );
    res
      .status(202)
      .json('input_kind' in run ? BuddyRunSchema.parse(run) : publicAutomationRun(run));
  });

  route.get('/api/buddies/automations/:automationId/runs', 400, async (req, res) => {
    const buddies = await getStore();
    res.json(
      buddies
        .listAutomationRuns(req.params.automationId, {
          limit:
            typeof req.query.limit === 'string' ? Number.parseInt(req.query.limit, 10) : undefined,
        })
        .map(publicAutomationRun)
    );
  });

  route.post('/api/buddies/automation-runs/:runId/cancel', 400, async (req, res) => {
    const scheduler = getScheduler();
    if (!scheduler) {
      res.status(503).json({ error: 'Buddy scheduler is not ready' });
      return;
    }
    res.json(publicAutomationRun(await scheduler.cancel(req.params.runId)));
  });

  // Legacy imported campaign status remains writable during the v1 transition.
  route.patch('/api/buddies/work-items/:id', 400, async (req, res) => {
    const { status, blockedReason, nextAction } = req.body ?? {};
    if (typeof status !== 'string') {
      res.status(400).json({ error: 'status is required' });
      return;
    }
    const buddies = await getStore();
    const workItem = buddies.updateWorkItemStatus(req.params.id, status as never, {
      blockedReason: typeof blockedReason === 'string' ? blockedReason : undefined,
      nextAction: typeof nextAction === 'string' ? nextAction : undefined,
    });
    res.json(workItem);
  });
}

import { randomUUID } from 'node:crypto';
import { MEMORY_NOTE_MAX_BYTES } from '@nbardy/buddies';
import type { BuddyDocumentRef, BuddyKnowledgeScope } from '@unleashd/shared';
import type { BuddiesStorePort } from './contract';
import { coordinationStore } from './coordination-store';
import { previewBuddyDocument } from './document-preview';
import type { BuddyOperationContext } from './operations';

export type KnowledgeAuthority = {
  actor: string;
  workspaceId: string;
  conversationId?: string | null;
  scope?: BuddyKnowledgeScope;
  provenance?: unknown;
};
export type KnowledgeDocument = {
  id: string | null;
  ref: BuddyDocumentRef;
  revision: number;
  content: string;
};
export interface KnowledgeStore {
  checkKnowledgeDocument(
    ref: BuddyDocumentRef,
    authority: KnowledgeAuthority,
    write?: boolean
  ): void;
  readKnowledgeDocument(ref: BuddyDocumentRef, authority: KnowledgeAuthority): KnowledgeDocument;
  replaceKnowledgeDocument(
    ref: BuddyDocumentRef,
    input: { key: string; baseRevision: number; content: string; reason: string },
    authority: KnowledgeAuthority
  ): { id: string; ref: BuddyDocumentRef; revision: number; auditId: string };
  listKnowledgeDocuments(
    input: {
      targetBuddyId: string;
      scope: BuddyKnowledgeScope;
      pattern?: string;
      limit?: number;
      since?: string;
      kinds?: string[];
    },
    authority: KnowledgeAuthority
  ): KnowledgeDocument[];
  listKnowledgeScopes(targetBuddyId: string, authority: KnowledgeAuthority): BuddyKnowledgeScope[];
  knowledgeAudienceRevision(authority: KnowledgeAuthority): string;
}
export function knowledgeStore(store: BuddiesStorePort): KnowledgeStore {
  if (typeof (store as unknown as KnowledgeStore).readKnowledgeDocument !== 'function')
    throw new Error('Scoped knowledge requires Buddies schema 26');
  return store as unknown as KnowledgeStore;
}
export function knowledgeAuthority(
  store: BuddiesStorePort,
  context: BuddyOperationContext
): KnowledgeAuthority {
  const run = context.coordinationRunId
    ? coordinationStore(store).getBuddyRun(context.coordinationRunId)
    : null;
  const teamTurn =
    !!context.automationRunId || !!context.delegatedByBuddyId || (run && run.input_kind !== 'chat');
  // Derive the audience from the actual run, never a requested document or prose.
  const projectId = run?.project_id ?? context.buddyProjectId;
  const scope: BuddyKnowledgeScope =
    context.knowledgeScope ??
    (teamTurn
      ? projectId
        ? { kind: 'project', projectId }
        : { kind: 'workspace', workspaceId: context.workspaceId }
      : { kind: 'owner_thread', conversationId: context.conversationId ?? 'unbound' });
  return {
    actor: context.buddyId,
    workspaceId: context.workspaceId,
    conversationId: scope.kind === 'owner_thread' ? scope.conversationId : context.conversationId,
    scope,
  };
}
export function scopedDocumentOperation(
  store: BuddiesStorePort,
  ref: BuddyDocumentRef,
  params: {
    content?: string;
    baseVersion?: number;
    reasoning?: string;
    key?: string;
    preview?: boolean;
  },
  authority: KnowledgeAuthority
) {
  const ledger = knowledgeStore(store);
  ledger.checkKnowledgeDocument(ref, authority, params.content !== undefined);
  if (params.content === undefined) return { data: ledger.readKnowledgeDocument(ref, authority) };
  if (ref.kind === 'note') validateNoteBody(params.content);
  if (!params.preview)
    return {
      data: ledger.replaceKnowledgeDocument(
        ref,
        {
          key: params.key!,
          baseRevision: params.baseVersion!,
          content: params.content,
          reason: params.reasoning!,
        },
        authority
      ),
    };
  const before = ledger.readKnowledgeDocument(ref, authority);
  return {
    data: previewBuddyDocument(
      {
        buddyId: ref.targetBuddyId,
        doc: ref.kind,
        content: before.content,
        revision: before.revision,
      },
      params.content,
      params.baseVersion!
    ),
  };
}

/** The body has one byte bound whether authored as a document or an evidence note. */
function validateNoteBody(body: string): void {
  if (Buffer.byteLength(body, 'utf8') > MEMORY_NOTE_MAX_BYTES)
    throw new Error(`Note body exceeds ${MEMORY_NOTE_MAX_BYTES} UTF-8 bytes`);
}

export function scopedNote(
  store: BuddiesStorePort,
  authority: KnowledgeAuthority,
  input: { topic?: string; body: string; evidence?: unknown[] },
  targetBuddyId = authority.actor
) {
  validateNoteBody(input.body);
  const name = `${new Date().toISOString()}:${randomUUID()}`;
  const ref: BuddyDocumentRef = {
    targetBuddyId,
    scope: authority.scope!,
    kind: 'note',
    name,
  };
  return knowledgeStore(store).replaceKnowledgeDocument(
    ref,
    {
      key: `note:${name}`,
      baseRevision: 0,
      content: JSON.stringify(input),
      reason: input.topic ?? 'Append evidence',
    },
    authority
  );
}

/** One authorized search for tools, maintenance and the owner Memory panel. */
export function recallKnowledge(
  store: BuddiesStorePort,
  authority: KnowledgeAuthority,
  input: {
    pattern: string;
    limit?: number;
    since?: string;
    scope?: 'current' | 'home' | 'all';
    regex?: boolean;
  },
  targetBuddyId = authority.actor
) {
  if (input.regex) throw new Error('Scoped knowledge search supports literal matching only');
  const limit = input.limit ?? 20;
  const documents = knowledgeStore(store).listKnowledgeDocuments(
    { ...input, targetBuddyId, scope: authority.scope!, limit: limit + 1 },
    authority
  );
  const legacy =
    authority.scope?.kind === 'owner_thread'
      ? store.recall?.(targetBuddyId, {
          pattern: input.pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
          workspace: authority.workspaceId,
          scope: input.scope ?? 'current',
          since: input.since,
          limit,
        })
      : undefined;
  const matches = [
    ...documents.map((doc) => ({
      ...doc,
      path: doc.ref.name ?? doc.ref.kind,
      workspace_id: authority.workspaceId,
      created_at: null,
    })),
    ...(legacy?.matches ?? []),
  ];
  return {
    pattern: input.pattern,
    matches: matches.slice(0, limit),
    truncated: matches.length > limit || !!legacy?.truncated,
  };
}

import { randomUUID } from 'node:crypto';
import { mkdir, open, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import {
  type ConversationConfig,
  type ConversationCreationMetadata,
  type PersistedConversationConfigRecord,
  PersistedConversationConfigRecordSchema,
  type Provider,
  ProviderSchema,
  type ResolvedExecutionConfig,
} from '@unleashd/shared';
import { z } from 'zod';

export const CONFIG_STORE_VERSION = 1 as const;
export const INITIAL_MESSAGE_DISPATCH_LEASE_MS = 15_000;

export { PersistedConversationConfigRecordSchema };
export type { PersistedConversationConfigRecord };

export const SessionBindingSchema =
  PersistedConversationConfigRecordSchema.shape.sessionBindings.element;

export type SessionBinding = PersistedConversationConfigRecord['sessionBindings'][number];

export const ConfigProvenanceSchema = PersistedConversationConfigRecordSchema.shape.provenance;

export type ConfigProvenance = PersistedConversationConfigRecord['provenance'];

const SessionIndexRecordSchema = z.object({
  version: z.literal(CONFIG_STORE_VERSION),
  conversationId: z.string().min(1),
});

export type ConfigStoreWarning =
  | {
      code: 'corrupt_record_quarantined';
      filePath: string;
      quarantinePath: string;
      error: string;
    }
  | {
      code: 'future_record_version';
      filePath: string;
      version: number;
    }
  | {
      code: 'session_index_update_failed';
      conversationId: string;
      error: string;
    };

export interface ConfigStoreLogger {
  warn(warning: ConfigStoreWarning): void;
}

export interface ConversationConfigStoreOptions {
  appDataRoot: string;
  now?: () => Date;
  logger?: ConfigStoreLogger;
  durableWrites?: boolean;
}

export interface ConversationConfigRecordListOptions {
  status?: PersistedConversationConfigRecord['status'];
}

export type ConfigRecordExpectation =
  | number
  | 'missing'
  | { configRevision: number; recordRevision: number };

interface SessionLookupIndex {
  scopes: number;
  ready: Promise<void>;
  bySession: Map<string, Set<string>>;
  byConversation: Map<string, readonly string[]>;
  pending?: Map<string, readonly string[]>;
}

export class ConfigRevisionConflictError extends Error {
  constructor(
    readonly expectedRevision: number,
    readonly actualRevision: number | undefined
  ) {
    super(
      `Configuration revision conflict: expected ${expectedRevision}, actual ${
        actualRevision ?? 'missing'
      }`
    );
    this.name = 'ConfigRevisionConflictError';
  }
}

export class UnsupportedConfigRecordVersionError extends Error {
  constructor(
    readonly filePath: string,
    readonly version: number
  ) {
    super(`Unsupported conversation config version ${version} in ${filePath}`);
    this.name = 'UnsupportedConfigRecordVersionError';
  }
}

/**
 * Durable authority for application-owned conversation configuration.
 *
 * Conversation records are authoritative. Session indexes are only accelerators:
 * lookup falls back to scanning records and repairs a missing or stale index.
 */
export class ConversationConfigStore {
  readonly rootDirectory: string;
  readonly conversationDirectory: string;
  readonly sessionDirectory: string;
  readonly quarantineDirectory: string;

  private readonly now: () => Date;
  private readonly logger?: ConfigStoreLogger;
  private readonly durableWrites: boolean;
  private readonly locks = new Map<string, Promise<void>>();
  private sessionLookupIndex: SessionLookupIndex | undefined;

  constructor(options: ConversationConfigStoreOptions) {
    if (!path.isAbsolute(options.appDataRoot)) {
      throw new Error('ConversationConfigStore appDataRoot must be absolute');
    }
    this.rootDirectory = path.join(options.appDataRoot, 'conversation-config', 'v1');
    this.conversationDirectory = path.join(this.rootDirectory, 'by-conversation');
    this.sessionDirectory = path.join(this.rootDirectory, 'by-session');
    this.quarantineDirectory = path.join(this.rootDirectory, 'quarantine');
    this.now = options.now ?? (() => new Date());
    this.logger = options.logger;
    this.durableWrites = options.durableWrites ?? false;
  }

  async getByConversationId(
    conversationId: string
  ): Promise<PersistedConversationConfigRecord | undefined> {
    const filePath = this.conversationPath(conversationId);
    return this.readRecord(filePath);
  }

  /**
   * Amortize missing-session lookup during a bulk import. The index contains only
   * identities; every hit still reads its authoritative record from disk. Writes
   * through this store maintain it, including writes while the initial scan runs.
   * Normal scan-and-repair behavior resumes when the last overlapping scope ends.
   * Unindexed writes by another process are discovered after the scope ends.
   */
  async withSessionLookupIndex<T>(operation: () => Promise<T>): Promise<T> {
    let index = this.sessionLookupIndex;
    if (!index) {
      index = {
        scopes: 0,
        ready: Promise.resolve(),
        bySession: new Map(),
        byConversation: new Map(),
        pending: new Map(),
      };
      this.sessionLookupIndex = index;
      index.ready = this.buildSessionLookupIndex(index);
    }
    index.scopes += 1;
    try {
      await index.ready;
      return await operation();
    } finally {
      index.scopes -= 1;
      if (index.scopes === 0 && this.sessionLookupIndex === index) {
        this.sessionLookupIndex = undefined;
      }
    }
  }

  async findBySession(
    provider: Provider,
    sessionId: string
  ): Promise<PersistedConversationConfigRecord | undefined> {
    ProviderSchema.parse(provider);
    const indexPath = this.sessionIndexPath({ provider, sessionId });
    const indexedConversationId = await this.readSessionIndex(indexPath);
    if (indexedConversationId) {
      const indexed = await this.getByConversationId(indexedConversationId);
      if (
        indexed &&
        recordSessionBindings(indexed).some(
          (binding) => binding.provider === provider && binding.sessionId === sessionId
        )
      ) {
        return indexed;
      }
    }

    const index = this.sessionLookupIndex;
    if (index) {
      await index.ready;
      const candidates = index.bySession.get(bindingKey({ provider, sessionId }));
      for (const conversationId of candidates ?? []) {
        let record: PersistedConversationConfigRecord | undefined;
        try {
          record = await this.getByConversationId(conversationId);
        } catch (error) {
          if (error instanceof UnsupportedConfigRecordVersionError) continue;
          throw error;
        }
        if (
          record &&
          recordSessionBindings(record).some(
            (binding) => binding.provider === provider && binding.sessionId === sessionId
          )
        ) {
          await this.writeSessionIndex({ provider, sessionId }, record.conversationId);
          return record;
        }
      }
      return undefined;
    }

    const records = await this.list();
    const found = records.find((record) =>
      recordSessionBindings(record).some(
        (binding) => binding.provider === provider && binding.sessionId === sessionId
      )
    );
    if (found) {
      await this.writeSessionIndex({ provider, sessionId }, found.conversationId);
    }
    return found;
  }

  async list(
    options: ConversationConfigRecordListOptions = {}
  ): Promise<PersistedConversationConfigRecord[]> {
    await mkdir(this.conversationDirectory, { recursive: true });
    const entries = await readdir(this.conversationDirectory, {
      withFileTypes: true,
    });
    const records = await Promise.all(
      entries
        .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
        .map(async (entry) => {
          try {
            return await this.readRecord(path.join(this.conversationDirectory, entry.name));
          } catch (error) {
            // A future record is intentionally left untouched. It must not
            // prevent supported records from rebuilding their derived indexes.
            if (error instanceof UnsupportedConfigRecordVersionError) return undefined;
            throw error;
          }
        })
    );
    return records
      .filter((record): record is PersistedConversationConfigRecord => record !== undefined)
      .filter((record) => options.status === undefined || record.status === options.status);
  }

  listActive(): Promise<PersistedConversationConfigRecord[]> {
    return this.list({ status: 'active' });
  }

  listDeleted(): Promise<PersistedConversationConfigRecord[]> {
    return this.list({ status: 'deleted' });
  }

  /**
   * Save a complete record. When expectedRevision is supplied it is compared
   * against durable state while holding the per-conversation lock.
   */
  async save(
    input: PersistedConversationConfigRecord,
    expectedRevision?: ConfigRecordExpectation
  ): Promise<PersistedConversationConfigRecord> {
    const parsed = PersistedConversationConfigRecordSchema.parse(input);
    return this.withLock(parsed.conversationId, async () => {
      const existing = await this.getByConversationId(parsed.conversationId);
      if (expectedRevision === 'missing' && existing) {
        throw new ConfigRevisionConflictError(-1, existing.configRevision);
      }
      if (typeof expectedRevision === 'number' && existing?.configRevision !== expectedRevision) {
        throw new ConfigRevisionConflictError(expectedRevision, existing?.configRevision);
      }
      if (
        typeof expectedRevision === 'object' &&
        (existing?.configRevision !== expectedRevision.configRevision ||
          existing.recordRevision !== expectedRevision.recordRevision)
      ) {
        throw new ConfigRevisionConflictError(
          expectedRevision.configRevision,
          existing?.configRevision
        );
      }

      const previousBindings = existing ? recordSessionBindings(existing) : [];
      const recordPath = this.conversationPath(parsed.conversationId);
      await this.atomicWriteJson(recordPath, parsed);
      this.trackSessionBindings(parsed.conversationId, recordSessionBindings(parsed));

      try {
        await this.reconcileSessionIndexes(
          parsed.conversationId,
          previousBindings,
          recordSessionBindings(parsed)
        );
      } catch (error) {
        this.logger?.warn({
          code: 'session_index_update_failed',
          conversationId: parsed.conversationId,
          error: errorMessage(error),
        });
      }
      return parsed;
    });
  }

  async create(input: {
    conversationId: string;
    sessionBindings?: readonly SessionBinding[];
    currentSession?: SessionBinding;
    workingDirectory?: string;
    creation?: ConversationCreationMetadata;
    config: ConversationConfig;
    lastResolvedConfig?: ResolvedExecutionConfig;
    provenance: ConfigProvenance;
  }): Promise<PersistedConversationConfigRecord> {
    const timestamp = this.now().toISOString();
    return this.save(
      {
        version: CONFIG_STORE_VERSION,
        conversationId: input.conversationId,
        sessionBindings: [...(input.sessionBindings ?? [])],
        status: 'active',
        ...(input.currentSession ? { currentSession: input.currentSession } : {}),
        ...(input.workingDirectory ? { workingDirectory: input.workingDirectory } : {}),
        ...(input.creation ? { creation: input.creation } : {}),
        config: input.config,
        recordRevision: 0,
        configRevision: 0,
        lastResolvedConfig: input.lastResolvedConfig,
        provenance: input.provenance,
        createdAt: timestamp,
        updatedAt: timestamp,
      },
      'missing'
    );
  }

  /**
   * Mark a conversation deleted without discarding its identity or session
   * indexes. Native transcript files can then be recognized as belonging to a
   * deleted application conversation after restart.
   */
  async delete(conversationId: string): Promise<boolean> {
    const existing = await this.getByConversationId(conversationId);
    if (!existing || existing.status === 'deleted') return false;
    await this.updateRecord(conversationId, (record) => ({
      ...record,
      status: 'deleted',
      deletedAt: this.now().toISOString(),
      updatedAt: this.now().toISOString(),
    }));
    return true;
  }

  /**
   * Physically remove a record. Reserved for rollback of a creation that was
   * never exposed; user deletion should use the durable tombstone above.
   */
  async purge(conversationId: string): Promise<boolean> {
    return this.withLock(conversationId, async () => {
      const existing = await this.getByConversationId(conversationId);
      if (!existing) return false;

      await rm(this.conversationPath(conversationId), { force: true });
      this.trackSessionBindings(conversationId, []);
      try {
        await this.reconcileSessionIndexes(conversationId, recordSessionBindings(existing), []);
      } catch (error) {
        this.logger?.warn({
          code: 'session_index_update_failed',
          conversationId,
          error: errorMessage(error),
        });
      }
      return true;
    });
  }

  /**
   * Replace an application-owned conversation ID while preserving provider
   * session bindings. Used to migrate legacy records that stored an opaque
   * provider session ID as their application identity.
   */
  async rekeyConversation(
    conversationId: string,
    replacementConversationId: string
  ): Promise<PersistedConversationConfigRecord> {
    const existing = await this.getByConversationId(conversationId);
    if (!existing) throw new Error(`Conversation config not found: ${conversationId}`);
    if (await this.getByConversationId(replacementConversationId)) {
      throw new ConfigRevisionConflictError(-1, 0);
    }

    await this.purge(conversationId);
    const replacement = { ...existing, conversationId: replacementConversationId };
    try {
      return await this.save(replacement, 'missing');
    } catch (error) {
      await this.save(existing, 'missing');
      throw error;
    }
  }

  async appendBranchLaunch(conversationId: string, digest: string, handoff: string) {
    return this.updateRecord(conversationId, (record) => {
      const branch = record.creation?.branch;
      if (record.status === 'deleted' || !branch) throw new Error('Launch branch unavailable');
      if (digest === branch.throughMessageId || branch.launches?.[digest]) return record;
      // Never silently discard launch context needed by an outstanding request.
      if (Object.keys(branch.launches ?? {}).length >= 128)
        throw new Error(
          'Background review launch history is full; start another owner conversation'
        );
      return {
        ...record,
        creation: {
          ...record.creation,
          branch: { ...branch, launches: { ...branch.launches, [digest]: handoff } },
        },
      };
    });
  }

  async setCurrentSession(
    conversationId: string,
    currentSession: SessionBinding
  ): Promise<PersistedConversationConfigRecord | undefined> {
    const parsedSession = SessionBindingSchema.parse(currentSession);
    return this.updateRecord(conversationId, (record) => {
      if (
        record.currentSession?.provider === parsedSession.provider &&
        record.currentSession.sessionId === parsedSession.sessionId
      ) {
        return record;
      }
      const historical = uniqueBindings([
        ...record.sessionBindings,
        ...(record.currentSession ? [record.currentSession] : []),
      ]).filter(
        (binding) =>
          binding.provider !== parsedSession.provider ||
          binding.sessionId !== parsedSession.sessionId
      );
      return {
        ...record,
        sessionBindings: historical,
        currentSession: parsedSession,
        updatedAt: this.now().toISOString(),
      };
    });
  }

  async addSessionBinding(
    conversationId: string,
    binding: SessionBinding
  ): Promise<PersistedConversationConfigRecord | undefined> {
    const parsedBinding = SessionBindingSchema.parse(binding);
    return this.updateRecord(conversationId, (record) => {
      if (
        record.currentSession?.provider === parsedBinding.provider &&
        record.currentSession.sessionId === parsedBinding.sessionId
      ) {
        return record;
      }
      const bindings = uniqueBindings([...record.sessionBindings, parsedBinding]);
      if (bindings.length === record.sessionBindings.length) return record;
      return {
        ...record,
        sessionBindings: bindings,
        updatedAt: this.now().toISOString(),
      };
    });
  }

  async markInitialMessageDispatched(
    conversationId: string,
    dispatchedAt = this.now()
  ): Promise<PersistedConversationConfigRecord | undefined> {
    return this.updateRecord(conversationId, (record) => {
      if (!record.creation?.initialMessage || record.creation.initialMessageDispatchedAt) {
        return record;
      }
      return {
        ...record,
        creation: {
          ...record.creation,
          initialMessageDispatchClaimedAt: undefined,
          initialMessageDispatchClaimToken: undefined,
          initialMessageDispatchedAt: dispatchedAt.toISOString(),
        },
        updatedAt: this.now().toISOString(),
      };
    });
  }

  /**
   * Atomically leases delivery of the creation message. Delivery is
   * acknowledged separately, so a crashed dispatcher can be recovered.
   */
  async claimInitialMessageDispatch(
    conversationId: string,
    claimedAt = this.now()
  ): Promise<PersistedConversationConfigRecord | undefined> {
    let claimed = false;
    const claimToken = randomUUID();
    const record = await this.updateRecord(conversationId, (current) => {
      claimed = false;
      if (
        current.status === 'deleted' ||
        !current.creation?.initialMessage ||
        current.creation.initialMessageDispatchedAt
      ) {
        return current;
      }
      const priorClaimedAt = current.creation.initialMessageDispatchClaimedAt;
      if (
        priorClaimedAt &&
        claimedAt.getTime() - Date.parse(priorClaimedAt) < INITIAL_MESSAGE_DISPATCH_LEASE_MS
      ) {
        return current;
      }
      claimed = true;
      return {
        ...current,
        creation: {
          ...current.creation,
          initialMessageDispatchClaimedAt: claimedAt.toISOString(),
          initialMessageDispatchClaimToken: claimToken,
        },
        updatedAt: claimedAt.toISOString(),
      };
    });
    return claimed ? record : undefined;
  }

  async completeInitialMessageDispatch(
    conversationId: string,
    claimToken: string,
    dispatchedAt = this.now()
  ): Promise<PersistedConversationConfigRecord | undefined> {
    let completed = false;
    const record = await this.updateRecord(conversationId, (current) => {
      if (
        current.status === 'deleted' ||
        !current.creation?.initialMessage ||
        current.creation.initialMessageDispatchedAt ||
        current.creation.initialMessageDispatchClaimToken !== claimToken
      ) {
        return current;
      }
      completed = true;
      return {
        ...current,
        creation: {
          ...current.creation,
          initialMessageDispatchClaimedAt: undefined,
          initialMessageDispatchClaimToken: undefined,
          initialMessageDispatchedAt: dispatchedAt.toISOString(),
        },
        updatedAt: dispatchedAt.toISOString(),
      };
    });
    return completed ? record : undefined;
  }

  async rebuildSessionIndex(): Promise<number> {
    const records = await this.list();
    const rebuiltRoot = `${this.sessionDirectory}.rebuild-${randomUUID()}`;
    await mkdir(rebuiltRoot, { recursive: true });
    let count = 0;
    for (const record of records) {
      for (const binding of recordSessionBindings(record)) {
        await this.atomicWriteJson(
          this.sessionIndexPath(binding, rebuiltRoot),
          {
            version: CONFIG_STORE_VERSION,
            conversationId: record.conversationId,
          },
          rebuiltRoot
        );
        count += 1;
      }
    }
    await rm(this.sessionDirectory, { recursive: true, force: true });
    await rename(rebuiltRoot, this.sessionDirectory);
    return count;
  }

  private async buildSessionLookupIndex(index: SessionLookupIndex): Promise<void> {
    const records = await this.list();
    for (const record of records) {
      this.updateSessionLookupIndex(
        index,
        record.conversationId,
        recordSessionBindings(record).map(bindingKey)
      );
    }
    // A write may have committed after readdir/readRecord captured the scan.
    // Replay its latest bindings so the scan cannot undo a creation or purge.
    for (const [conversationId, keys] of index.pending ?? []) {
      this.updateSessionLookupIndex(index, conversationId, keys);
    }
    index.pending = undefined;
  }

  private trackSessionBindings(conversationId: string, bindings: readonly SessionBinding[]): void {
    const index = this.sessionLookupIndex;
    if (!index) return;
    const keys = bindings.map(bindingKey);
    if (index.pending) {
      index.pending.set(conversationId, keys);
    } else {
      this.updateSessionLookupIndex(index, conversationId, keys);
    }
  }

  private updateSessionLookupIndex(
    index: SessionLookupIndex,
    conversationId: string,
    keys: readonly string[]
  ): void {
    for (const key of index.byConversation.get(conversationId) ?? []) {
      const candidates = index.bySession.get(key);
      candidates?.delete(conversationId);
      if (candidates?.size === 0) index.bySession.delete(key);
    }
    index.byConversation.delete(conversationId);
    if (keys.length === 0) return;
    index.byConversation.set(conversationId, keys);
    for (const key of keys) {
      const candidates = index.bySession.get(key) ?? new Set<string>();
      candidates.add(conversationId);
      index.bySession.set(key, candidates);
    }
  }

  private async readRecord(
    filePath: string
  ): Promise<PersistedConversationConfigRecord | undefined> {
    let source: string;
    try {
      source = await readFile(filePath, 'utf8');
    } catch (error) {
      if (isMissingFileError(error)) return undefined;
      throw error;
    }

    let decoded: unknown;
    try {
      decoded = JSON.parse(source);
    } catch (error) {
      await this.quarantine(filePath, errorMessage(error));
      return undefined;
    }

    const version = objectVersion(decoded);
    if (version !== undefined && version > CONFIG_STORE_VERSION) {
      this.logger?.warn({ code: 'future_record_version', filePath, version });
      throw new UnsupportedConfigRecordVersionError(filePath, version);
    }

    const parsed = PersistedConversationConfigRecordSchema.safeParse(decoded);
    if (!parsed.success) {
      await this.quarantine(filePath, parsed.error.message);
      return undefined;
    }
    return parsed.data;
  }

  private async updateRecord(
    conversationId: string,
    update: (record: PersistedConversationConfigRecord) => PersistedConversationConfigRecord
  ): Promise<PersistedConversationConfigRecord | undefined> {
    for (let attempt = 0; attempt < 3; attempt += 1) {
      const existing = await this.getByConversationId(conversationId);
      if (!existing) return undefined;
      const next = update(existing);
      if (next === existing) return existing;
      try {
        return await this.save(
          { ...next, recordRevision: existing.recordRevision + 1 },
          {
            configRevision: existing.configRevision,
            recordRevision: existing.recordRevision,
          }
        );
      } catch (error) {
        if (!(error instanceof ConfigRevisionConflictError) || attempt === 2) throw error;
      }
    }
    return undefined;
  }

  private async readSessionIndex(filePath: string): Promise<string | undefined> {
    try {
      const decoded = JSON.parse(await readFile(filePath, 'utf8'));
      const parsed = SessionIndexRecordSchema.safeParse(decoded);
      return parsed.success ? parsed.data.conversationId : undefined;
    } catch (error) {
      if (isMissingFileError(error) || error instanceof SyntaxError) return undefined;
      throw error;
    }
  }

  private async quarantine(filePath: string, error: string): Promise<void> {
    await mkdir(this.quarantineDirectory, { recursive: true });
    const quarantinePath = path.join(
      this.quarantineDirectory,
      `${path.basename(filePath, '.json')}-${this.now().toISOString().replaceAll(':', '-')}.json`
    );
    try {
      await rename(filePath, quarantinePath);
    } catch (renameError) {
      if (!isMissingFileError(renameError)) throw renameError;
      return;
    }
    this.logger?.warn({
      code: 'corrupt_record_quarantined',
      filePath,
      quarantinePath,
      error,
    });
  }

  private async reconcileSessionIndexes(
    conversationId: string,
    previous: readonly SessionBinding[],
    next: readonly SessionBinding[]
  ): Promise<void> {
    const nextKeys = new Set(next.map(bindingKey));
    for (const binding of previous) {
      if (!nextKeys.has(bindingKey(binding))) {
        const indexPath = this.sessionIndexPath(binding);
        const indexedId = await this.readSessionIndex(indexPath);
        if (indexedId === conversationId) {
          await rm(indexPath, { force: true });
        }
      }
    }
    for (const binding of next) {
      await this.writeSessionIndex(binding, conversationId);
    }
  }

  private async writeSessionIndex(binding: SessionBinding, conversationId: string): Promise<void> {
    await this.atomicWriteJson(this.sessionIndexPath(binding), {
      version: CONFIG_STORE_VERSION,
      conversationId,
    });
  }

  private conversationPath(conversationId: string): string {
    const parsed = z.string().min(1).parse(conversationId);
    return path.join(this.conversationDirectory, `${encodeSessionId(parsed)}.json`);
  }

  private sessionIndexPath(binding: SessionBinding, root = this.sessionDirectory): string {
    const parsed = SessionBindingSchema.parse(binding);
    return path.join(root, parsed.provider, `${encodeSessionId(parsed.sessionId)}.json`);
  }

  private async atomicWriteJson(
    filePath: string,
    value: unknown,
    syncRoot?: string
  ): Promise<void> {
    const directory = path.dirname(filePath);
    await mkdir(directory, { recursive: true });
    const temporaryPath = path.join(
      directory,
      `.${path.basename(filePath)}.${process.pid}.${randomUUID()}.tmp`
    );
    try {
      await writeFile(temporaryPath, `${JSON.stringify(value, null, 2)}\n`, {
        encoding: 'utf8',
        flag: 'wx',
      });
      if (this.durableWrites) {
        const temporary = await open(temporaryPath, 'r');
        try {
          await temporary.sync();
        } finally {
          await temporary.close();
        }
      }
      await rename(temporaryPath, filePath);
      if (this.durableWrites) {
        const directoryHandle = await open(syncRoot ?? directory, 'r');
        try {
          await directoryHandle.sync();
        } finally {
          await directoryHandle.close();
        }
      }
    } catch (error) {
      await rm(temporaryPath, { force: true });
      throw error;
    }
  }

  private async withLock<T>(key: string, operation: () => Promise<T>): Promise<T> {
    const prior = this.locks.get(key) ?? Promise.resolve();
    let release!: () => void;
    const current = new Promise<void>((resolve) => {
      release = resolve;
    });
    const tail = prior.catch(() => undefined).then(() => current);
    this.locks.set(key, tail);
    await prior.catch(() => undefined);
    try {
      return await operation();
    } finally {
      release();
      if (this.locks.get(key) === tail) this.locks.delete(key);
    }
  }
}

function encodeSessionId(sessionId: string): string {
  return Buffer.from(sessionId, 'utf8').toString('base64url');
}

function bindingKey(binding: SessionBinding): string {
  return `${binding.provider}\0${binding.sessionId}`;
}

function uniqueBindings(bindings: readonly SessionBinding[]): SessionBinding[] {
  const unique = new Map<string, SessionBinding>();
  for (const binding of bindings) unique.set(bindingKey(binding), binding);
  return [...unique.values()];
}

function recordSessionBindings(record: PersistedConversationConfigRecord): SessionBinding[] {
  return uniqueBindings([
    ...record.sessionBindings,
    ...(record.currentSession ? [record.currentSession] : []),
  ]);
}

function objectVersion(value: unknown): number | undefined {
  if (typeof value !== 'object' || value === null || !('version' in value)) return undefined;
  return typeof value.version === 'number' ? value.version : undefined;
}

function isMissingFileError(error: unknown): error is NodeJS.ErrnoException {
  return error instanceof Error && 'code' in error && error.code === 'ENOENT';
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

